mapper.select:
/* CastUserSnapshotMapper.retrieveNextRsrcNo */
SELECT LPAD(PMOWN.SQ1_TN_PM_SMLT_USER_RSRC.NEXTVAL, 3, '0') AS RSRC_NO
FROM DUAL

mapper.insert:
/* CastUserSnapshotMapper.insertRsrcMstr */
INSERT INTO PMOWN.${mstrTableNm} (
    ${mstrIdColumnNm}, ${mstrNmColumnNm}, PRCS_STTS_CD, CFMTN_YN, USE_YN,
    FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT
) VALUES (
    #{snapshot.rsrcNo},
    '사용자 시뮬레이션 ' || #{snapshot.smltId} || ' ' || #{snapshot.tmnlId},
    '99', 'Y', 'Y',
    #{snapshot.loginUserId}, #{snapshot.loginIpAddr}, CURRENT_TIMESTAMP
)

/* CastUserSnapshotMapper.insertSchdlAtrbFromDaily */
INSERT INTO PMOWN.TN_PM_SMLT_SCHDL_ATRB ( SCHDL_ATRB_GROUP_ID, DOM_INTL_SE_CD, ARR_DEP_SE_CD, TMNL_ID, ALN_CD, FLTNM, DEP_ARR_YMD, DEP_ARR_HM, PREDC_HM, ACTL_HM, ARR_DEP_ARPT_CD, ACST_NO, GATE_NO, ARCFT_STGCP, BDPSG_CNT, TRNS_BDPSG_CNT, CRSL_NO, ARCFT_SUBTYPE_CD, IRR_FLT_YN, TDFLT_YN, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) SELECT #{rsrcNo}, X.DOM_INTL_SE_CD, X.ARR_DEP_SE_CD, X.TMNL_ID, X.ALN_CD, X.FLTNM, X.DEP_ARR_YMD, X.DEP_ARR_HM, X.PREDC_HM, X.ACTL_HM, X.ARPT_CD, X.ACST_NO, X.GATE_NO, X.ARCFT_STGCP, ROUND(NVL(X.BDPSG_CNT, 0) * (100 + X.AJMT_RT) / 100), X.TRNS_BDPSG_CNT, X.CRSL_NO, X.ARCFT_SUBTYPE_CD, X.IRR_FLT_YN, X.TDFLT_YN, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM ( SELECT A.DOM_INTL_SE_CD, A.ARR_DEP_SE_CD, A.TMNL_ID, A.ALN_CD, A.FLTNM, A.GD_SE_YMD AS DEP_ARR_YMD, A.SCHDL_HM AS DEP_ARR_HM, A.PREDC_HM, A.ACTL_HM, A.ARPT_CD, A.ACST_NO, A.GATE_NO, A.ARCFT_STGCP, A.RSVT_BDPSG_CNT AS BDPSG_CNT, A.RSVT_TRNS_BDPSG_CNT AS TRNS_BDPSG_CNT, A.CRSL_NO, A.ARCFT_SUBTYPE_CD, A.GD_IRR_YN AS IRR_FLT_YN, A.TDFLT_YN, CASE WHEN A.TMNL_ID NOT IN (#{item}) THEN 0 WHEN #{ajmtTypeCd} = 'HOURLY' THEN NVL(( SELECT T.AJMT_RT FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG_TMZN_AJMT T WHERE T.SMLT_ID = #{smltId} AND T.TMNL_ID = #{tmnlId} AND NVL(A.PREDC_HM, A.SCHDL_HM) >= T.BGNG_HM AND NVL(A.PREDC_HM, A.SCHDL_HM) < NVL(T.END_HM, '2400') AND ROWNUM = 1 ), 0) ELSE #{ajmtRt} END AS AJMT_RT,
ROW_NUMBER() OVER ( PARTITION BY A.ARR_DEP_SE_CD, A.FLTNM, A.GD_SE_YMD, A.SCHDL_HM ORDER BY A.RSVT_BDPSG_CNT DESC NULLS LAST ) AS RN FROM GOOWN.TN_GO_GD_DATA A WHERE A.GD_SE_YMD = #{excnYmd} AND A.CSHR_STTS_CD != 'SL' AND A.DLY_RSN_CD NOT IN ('2', '3') AND A.TMNL_ID IN ('P', 'P01', 'P02', 'P03') AND A.ARCFT_USE_SE_CD = '0' AND A.GD_FLT_PRPS_CD IN ('00', '05') AND A.PSG_CGO_SE_CD = 'Y' AND A.FRY_YN = 'N' AND A.LCRFT_YN = 'N' AND A.SCHDL_HM IS NOT NULL ) X WHERE X.RN = 1
